def copy_bags(apps, schema_editor):
    """Each signed-in buyer's bag (accounts.BagLine) becomes their basket,
    with today's price as the snapshot. BagLine is left as it is, unused,
    to be dropped in a later release."""
    BagLine = apps.get_model("accounts", "BagLine")
    Basket = apps.get_model("marketplace", "Basket")
    BasketLine = apps.get_model("marketplace", "BasketLine")
    baskets = {}
    for line in BagLine.objects.select_related("product", "option").order_by("added_at", "pk"):
        basket = baskets.get(line.account_id)
        if basket is None:
            basket, _ = Basket.objects.get_or_create(account_id=line.account_id)
            baskets[line.account_id] = basket
        price = (
            line.option.price
            if line.option_id and line.option.price is not None
            else line.product.price
        )
        BasketLine.objects.get_or_create(
            basket=basket,
            product_id=line.product_id,
            option_id=line.option_id,
            defaults={"quantity": line.quantity, "price_snapshot": price},
        )


